       font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
       color: var(--text);
       background:
         radial-gradient(circle at top, rgba(59, 130, 246, 0.22), transparent 32%),
         linear-gradient(180deg, #0f172a 0%, var(--bg) 100%);
     }

     .card {
       width: min(100%, 420px);
       padding: 32px;
       border: 1px solid var(--panel-border);
       border-radius: 20px;
       background: var(--panel);
       box-shadow: var(--shadow);
       backdrop-filter: blur(16px);
     }

     h1 {
       margin: 0 0 10px;
       font-size: 1.6rem;
       line-height: 1.2;
     }

     p {
       margin: 0;
       color: var(--muted);
       line-height: 1.5;
     }

     form {
       margin-top: 24px;
     }

     .form-field {
       display: grid;
       gap: 8px;
       margin-bottom: 20px;
     }

     .checkbox-row {
       display: flex;
       align-items: flex-start;
       gap: 12px;
       padding: 14px 16px;
       border: 1px solid rgba(148, 163, 184, 0.22);
       border-radius: 14px;
       background: rgba(15, 23, 42, 0.7);
     }

     input[type="checkbox"] {
       width: 18px;
       height: 18px;
       margin-top: 2px;
       accent-color: var(--accent-strong);
       cursor: pointer;
       flex-shrink: 0;
     }

     label {
       font-weight: 600;
       cursor: pointer;
     }

     .helper-text {
       font-size: 0.92rem;
       color: var(--muted);
     }

     button {
       width: 100%;
       border: 0;
       border-radius: 14px;
       padding: 14px 16px;
       font: inherit;
       font-weight: 700;
       color: #eff6ff;
       background: linear-gradient(135deg, var(--accent) 0%, var(--accent-strong) 100%);
       cursor: pointer;
       transition: transform 140ms ease, box-shadow 140ms ease, filter 140ms ease;
       box-shadow: 0 12px 30px rgba(59, 130, 246, 0.28);
     }

     button:hover {
       transform: translateY(-1px);
       filter: brightness(1.05);
     }

     button:focus-visible,
     input:focus-visible {
       outline: 3px solid rgba(96, 165, 250, 0.45);
       outline-offset: 3px;
     }

     .status {
       min-height: 1.5em;
       margin-top: 14px;
       font-size: 0.95rem;
       color: var(--success);
     }
   </style>
 </head>
 <body>
   <main class="card">
     <h1>Confirm your consent</h1>
     <p>Please review the terms of use before continuing.</p>

     <form id="consent-form" novalidate>
       <div class="form-field">
         <div class="checkbox-row">
           <input
             id="terms"
             name="terms"
             type="checkbox"
             required
             aria-describedby="terms-help"
           >
           <label for="terms">I agree to the terms of use.</label>
         </div>
         <p id="terms-help" class="helper-text">Required to continue with submission.</p>
       </div>

       <button type="submit">Submit</button>
       <p id="status" class="status" aria-live="polite"></p>
     </form>
   </main>

   <script>
     const form = document.getElementById("consent-form");
     const checkbox = document.getElementById("terms");
     const status = document.getElementById("status");

     form.addEventListener("submit", function (event) {
       event.preventDefault();

       if (!checkbox.checked) {
         checkbox.reportValidity();
         status.textContent = "";
         return;
       }

       status.textContent = "Consent recorded successfully.";
     });
   </script>
 </body>
 </html>

